<script setup>import { ref,onMounted } from 'vue'; import api from '@/api/client'; const items=ref([]); const error=ref(''); onMounted(async()=>{try{items.value=(await api.get('/notification-logs')).data.data}catch(e){error.value='Notifikasi belum dapat dimuat.'}})</script><template><section><h1>Log notifikasi</h1><p v-if="error">{{error}}</p><ul><li v-for="item in items" :key="item.id">{{item.type}}: {{item.status}}</li></ul></section></template>